import{_ as o,o as l,c as d,a2 as i}from"./chunks/framework.CHeM0PsO.js";const s=JSON.parse('{"title":"指令索引","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/commands.md","filePath":"projects/lotus-plugin/docs/commands.md"}'),c={name:"projects/lotus-plugin/docs/commands.md"};function a(t,e,r,h,n,u){return l(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="指令索引" tabindex="-1">指令索引 <a class="header-anchor" href="#指令索引" aria-label="Permalink to &quot;指令索引&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><p>profile 后缀默认支持 <code>1..255</code>。普通指令没有后缀时使用 profile 1，体力查询没有后缀时汇总当前 QQ 的所有 profile；例如 <code>#扫码登录2</code>、<code>#体力2</code>、<code>*末日2</code>。</p><p>按功能阅读说明见 <a href="./README.html">文档目录</a> 和 <a href="./features/README.html">小功能索引</a>。</p><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h2><ul><li><code>#荷花状态</code></li><li><code>#荷花帮助</code></li><li><code>#自动签到帮助</code></li><li><code>#荷花配置</code></li><li><code>#荷花配置2</code></li><li><code>#捐赠</code></li></ul><h2 id="登录与-profile" tabindex="-1">登录与 profile <a class="header-anchor" href="#登录与-profile" aria-label="Permalink to &quot;登录与 profile&quot;">​</a></h2><ul><li><code>#扫码登录</code></li><li><code>#扫码登录2</code></li><li><code>#二维码登录2</code></li><li><code>#辅助登录2</code></li><li><code>#刷新cookie</code></li><li><code>#刷新cookie2</code></li><li><code>#刷新自动签到2</code></li><li><code>#登录列表</code></li><li><code>#同步角色2</code></li><li><code>#同步登录2</code></li><li><code>#清除登录2</code></li><li><code>#删除cookie2</code></li></ul><p>账号密码登录已经裁剪；发送相关入口时会提示改用扫码登录。</p><h2 id="profile-设置" tabindex="-1">profile 设置 <a class="header-anchor" href="#profile-设置" aria-label="Permalink to &quot;profile 设置&quot;">​</a></h2><ul><li><code>#注册自动签到2</code></li><li><code>#注册本群签到2</code></li><li><code>#绑定通知群2</code></li><li><code>#设置通知私聊2</code></li><li><code>#设置通知群聊2</code></li><li><code>#启用社区签到2</code></li><li><code>#关闭社区签到2</code></li><li><code>#启用原神签到2</code></li><li><code>#关闭星铁签到2</code></li><li><code>#启用绝区零签到2</code></li><li><code>#启用全部游戏签到2</code></li><li><code>#关闭全部游戏签到2</code></li><li><code>#开启签到通知2</code></li><li><code>#关闭签到通知2</code></li><li><code>#随机签到时间2</code>（仅主人）</li><li><code>#固定签到时间2 04:30</code>（仅主人）</li><li><code>#跟随全局签到时间2</code>（仅主人）</li><li><code>#绑定原神UID2 100000001</code></li><li><code>#绑定星铁UID2 100000001</code></li><li><code>#绑定绝区零UID2 10000001</code></li><li><code>#绑定国际服cookie2 &lt;cookie&gt;</code></li><li><code>#启用国际服签到2</code></li><li><code>#设置国际服语言2 zh-cn</code></li><li><code>#绑定云原神token2 &lt;token&gt;</code></li><li><code>#启用云原神签到2</code></li><li><code>#绑定云绝区零token2 &lt;token&gt;</code></li><li><code>#启用云绝区零签到2</code></li></ul><p>绑定 UID 时，指定的 profile 编号与 UID 之间须有空格；直接把完整 UID 接在指令后面表示绑定到 profile 1。</p><h2 id="签到与调度" tabindex="-1">签到与调度 <a class="header-anchor" href="#签到与调度" aria-label="Permalink to &quot;签到与调度&quot;">​</a></h2><ul><li><p><code>#米游社功能</code>：签到、社区任务和米游币兑换总页。</p></li><li><p><code>#荷花面板</code>：同一总页；机器人主人可进入全局配置。</p></li><li><p><code>#测试签到2</code></p></li><li><p><code>#开始签到2</code></p></li><li><p><code>#手动签到2</code></p></li><li><p><code>#补签2</code></p></li><li><p><code>#我的签到时间</code></p></li><li><p><code>#生成签到计划</code></p></li><li><p><code>#签到随机模式</code></p></li><li><p><code>#签到固定模式 04:30</code></p></li><li><p><code>#签到计划生成 00:00</code></p></li><li><p><code>#执行到期签到</code></p></li><li><p><code>#签到名单列表</code></p></li><li><p><code>#自动签到日志</code></p></li><li><p><code>#批量刷新签到</code></p></li></ul><h2 id="体力查询" tabindex="-1">体力查询 <a class="header-anchor" href="#体力查询" aria-label="Permalink to &quot;体力查询&quot;">​</a></h2><ul><li><code>#全部体力</code></li><li><code>#全部体力2</code></li><li><code>#体力2</code></li><li><code>#树脂2</code></li><li><code>#便笺2</code></li><li><code>*体力2</code></li><li><code>#星铁体力2</code></li><li><code>%体力2</code></li><li><code>#绝区零体力2</code></li></ul><h2 id="面板查询" tabindex="-1">面板查询 <a class="header-anchor" href="#面板查询" aria-label="Permalink to &quot;面板查询&quot;">​</a></h2><ul><li><code>#更新面板2</code></li><li><code>#星铁更新面板2</code></li><li><code>*更新面板2</code></li><li><code>#绝区零更新面板2</code></li><li><code>%更新面板2</code></li><li><code>#修复原铁面板 间隔8</code></li><li><code>#面板角色2</code></li><li><code>*面板角色2</code></li><li><code>#火神面板2</code></li><li><code>*狼尊面板3</code></li><li><code>%练度统计2</code></li><li><code>%角色2</code></li><li><code>#练度统计2</code></li><li><code>#角色查询2</code></li><li><code>#天赋统计2</code></li><li><code>*天赋统计2</code>、<code>*行迹统计2</code></li><li><code>#刷新天赋2</code>、<code>*刷新行迹2</code></li><li><code>#圣遗物列表2</code>、<code>*遗器列表2</code></li><li><code>#火神排名2</code>、<code>*流萤排名2</code></li><li><code>#重载面板2</code>、<code>*重载面板2</code></li><li><code>#删除面板2</code>、<code>*删除面板2</code>：进入对应 UID 的删除确认，仍遵循喵喵权限与确认流程。</li></ul><h2 id="战绩查询-原神、绝区零" tabindex="-1">战绩查询-原神、绝区零 <a class="header-anchor" href="#战绩查询-原神、绝区零" aria-label="Permalink to &quot;战绩查询-原神、绝区零&quot;">​</a></h2><ul><li><code>#深渊2</code></li><li><code>#幻想2</code></li><li><code>#危战2</code></li><li><code>%防卫战2</code></li><li><code>%危局2</code></li><li><code>%临界2</code></li><li><code>%月报2</code></li></ul><h2 id="战绩查询-星铁" tabindex="-1">战绩查询-星铁 <a class="header-anchor" href="#战绩查询-星铁" aria-label="Permalink to &quot;战绩查询-星铁&quot;">​</a></h2><ul><li><code>*混沌2</code></li><li><code>*虚构2</code></li><li><code>*末日2</code></li><li><code>*异相2</code></li></ul><h2 id="抽卡记录" tabindex="-1">抽卡记录 <a class="header-anchor" href="#抽卡记录" aria-label="Permalink to &quot;抽卡记录&quot;">​</a></h2><ul><li><code>#更新抽卡记录2</code></li><li><code>#更新小助手抽卡记录2</code>：自动同步该 profile 的提瓦特小助手原神记录。</li><li><code>*更新抽卡记录2</code></li><li><code>#星铁更新抽卡记录2</code></li><li><code>%更新抽卡记录2</code></li><li><code>#绝区零刷新抽卡链接2</code></li><li><code>#更新全部抽卡记录</code></li><li><code>#抽卡记录2</code>、<code>*抽卡记录2</code>：使用对应 profile 查看喵喵抽卡明细。</li><li><code>#角色全部记录2</code>、<code>*光锥全部记录2</code>：查看指定卡池的全部明细，按喵喵设置分页。</li><li><code>#角色统计2</code>、<code>*角色全部统计2</code>：查看指定卡池统计，保留“全部”选择。</li><li><code>%抽卡记录2</code>、<code>%抽卡分析2</code>、<code>%抽卡统计2</code>：调用 ZZZ-Plugin 的抽卡分析页。</li></ul><p>记录与统计支持 <code>全部角色记录</code> 和 <code>角色全部记录</code> 两种顺序。新手池、星铁联动池及不指定卡池的 <code>#全部记录</code> 保留兼容显示入口；<code>#全部统计</code> 使用喵喵全卡池统计。</p><h2 id="队伍伤害-原神" tabindex="-1">队伍伤害-原神 <a class="header-anchor" href="#队伍伤害-原神" aria-label="Permalink to &quot;队伍伤害-原神&quot;">​</a></h2><ul><li><code>#队伍伤害 神鹤万心</code></li><li><code>#队伍伤害2 宵宫 夜兰 茜特菈莉 希诺宁</code></li><li><code>#队伍伤害详情2 宵宫夜兰茜特菈莉希诺宁</code></li></ul><h2 id="队伍伤害-星铁" tabindex="-1">队伍伤害-星铁 <a class="header-anchor" href="#队伍伤害-星铁" aria-label="Permalink to &quot;队伍伤害-星铁&quot;">​</a></h2><ul><li><code>*队伍伤害 迷迷遐风</code></li><li><code>*队伍伤害2 银狼lv999 藿藿 风堇 小伊卡</code></li><li><code>#星铁队伍伤害过程2 银狼 藿藿 风堇 小伊卡</code></li></ul><p>角色名可以空格分隔；原神也会尝试识别连续拼接的角色名。</p><h2 id="插件管理面板" tabindex="-1">插件管理面板 <a class="header-anchor" href="#插件管理面板" aria-label="Permalink to &quot;插件管理面板&quot;">​</a></h2><ul><li>主人私聊发送 <code>#荷花管理面板</code> 或 <code>#荷花配置</code>，获取独立侧栏管理页。</li><li>登录链接默认 10 分钟内一次有效，管理浏览器令牌默认 24 小时；均可在“网页登录”设置中调整。令牌在有效期内跨机器人重启保留，退出即撤销，普通用户无法申请或访问配置接口。</li></ul><h2 id="米游币兑换网页" tabindex="-1">米游币兑换网页 <a class="header-anchor" href="#米游币兑换网页" aria-label="Permalink to &quot;米游币兑换网页&quot;">​</a></h2><ul><li>私聊发送 <code>#米游币兑换</code> 或 <code>#米游币商城</code>，获取自己的专属网页登录链接。</li><li>在网页切换 profile、查看商品与官方开放时间、选择兑换目标并创建预约。</li></ul><p>详见<a href="./features/coin-shop.html">米游币兑换网页</a>。</p><h2 id="前瞻兑换码" tabindex="-1">前瞻兑换码 <a class="header-anchor" href="#前瞻兑换码" aria-label="Permalink to &quot;前瞻兑换码&quot;">​</a></h2><ul><li><code>#兑换码</code> / <code>#原神兑换码</code></li><li><code>*兑换码</code> / <code>#星铁兑换码</code> / <code>#崩铁兑换码</code></li><li><code>%兑换码</code> / <code>#绝区零兑换码</code> / <code>#zzzcode</code></li><li><code>#崩三兑换码</code> / <code>#崩坏三兑换码</code> / <code>#崩坏3兑换码</code></li><li><code>#星布谷地公测兑换码</code>：独立的公测兑换码查询，使用已核实的固定官方公告资料。</li></ul><p>支持加“前瞻”或“直播”，例如 <code>#星铁前瞻兑换码</code>。查询官方活动中的全部已发布兑换码，显示官方有效期（北京时间）；过期时明确提示，不发送旧码。详见<a href="./features/redeem-codes.html">前瞻兑换码</a>。</p><h2 id="日历与素材" tabindex="-1">日历与素材 <a class="header-anchor" href="#日历与素材" aria-label="Permalink to &quot;日历与素材&quot;">​</a></h2><ul><li><code>#日历</code></li><li><code>喵喵日历</code></li><li><code>*日历</code></li><li><code>#星铁日历</code></li><li><code>%日历</code></li><li><code>#绝区零日历</code></li><li><code>#今日素材</code></li><li><code>#明日天赋</code></li><li><code>#周一材料</code></li></ul><h2 id="图鉴与成就" tabindex="-1">图鉴与成就 <a class="header-anchor" href="#图鉴与成就" aria-label="Permalink to &quot;图鉴与成就&quot;">​</a></h2><ul><li><code>#图鉴 星见雅</code></li><li><code>#星见雅</code></li><li><code>#雾切之回光</code></li><li><code>#冰封迷途的勇士</code></li><li><code>#星见雅天赋</code></li><li><code>*黄泉星魂</code></li><li><code>%仪玄影画</code></li><li><code>#本期幻想图鉴</code></li><li><code>#下期幽境危战</code></li><li><code>*上期末日图鉴</code></li><li><code>*异相</code></li><li><code>%下期防卫战</code></li><li><code>#图鉴状态</code></li><li><code>#更新图鉴</code></li><li><code>#检查图鉴更新</code></li><li><code>#全量更新图鉴</code></li><li><code>#图鉴帮助</code></li><li><code>#成就</code></li><li><code>#成就目录2</code></li><li><code>#成就查漏2</code></li><li><code>#成就导入2</code></li><li><code>#尘世巡游第三辑2</code></li><li><code>#成就尘世巡游第三辑2</code></li></ul><p>成就导入只接收椰羊导出的 JSON。分类名里的中点号可以省略；分类详情会自动分页并按顺序发送。</p><h2 id="b-站" tabindex="-1">B 站 <a class="header-anchor" href="#b-站" aria-label="Permalink to &quot;B 站&quot;">​</a></h2><ul><li>发送 BV/av/长链/短链/QQ 分享卡片</li><li><code>#搜视频</code>（兼容 <code>#荷花搜视频</code>）</li><li><code>#荷花搜视频 关键词</code></li><li><code>#看1</code></li><li><code>#荷花看视频 BV号</code></li><li><code>#B站下载 BV号</code></li><li><code>#荷花下载 https://www.bilibili.com/video/...</code></li><li><code>#B站登录</code></li></ul><p>直播只发送信息卡和独立播放器链接，不做直播下载。</p><h2 id="抖音" tabindex="-1">抖音 <a class="header-anchor" href="#抖音" aria-label="Permalink to &quot;抖音&quot;">​</a></h2><ul><li>直接发送抖音作品分享链接或分享卡片。</li><li><code>#抖音下载 &lt;作品链接&gt;</code></li><li>支持视频、图集、混合合辑、动态图片和文章；多项默认打包发送。</li><li>配置说明：<a href="./douyin.html">抖音作品解析与下载</a>。</li></ul><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><ul><li><code>#初始化环境</code>：验证码模型、TuneWeave 与 FFmpeg；原签到、工具初始化指令作为兼容别名。</li><li><code>#启动testnine服务</code></li><li><code>#停止testnine服务</code></li><li><code>#testnine状态</code></li></ul><h2 id="点歌与音乐登录" tabindex="-1">点歌与音乐登录 <a class="header-anchor" href="#点歌与音乐登录" aria-label="Permalink to &quot;点歌与音乐登录&quot;">​</a></h2><ul><li><code>#点歌 歌名</code> / <code>#网易点歌 歌名</code></li><li><code>#QQ点歌 歌名</code> / <code>#酷狗点歌 歌名</code> / <code>#酷我点歌 歌名</code></li><li><code>#咪咕点歌 歌名</code> / <code>#汽水点歌 歌名</code></li><li>搜索后输入数字或 <code>#听1</code>；<code>#下一页</code> 翻页，<code>#取消</code> 退出。</li><li><code>#音乐登录</code>：主人选择平台、二维码方式后扫码。</li><li><code>#音乐帮助</code></li></ul><h2 id="网易云合伙人" tabindex="-1">网易云合伙人 <a class="header-anchor" href="#网易云合伙人" aria-label="Permalink to &quot;网易云合伙人&quot;">​</a></h2><ul><li><code>#初始化TuneWeave</code></li><li><code>#TuneWeave状态</code></li><li><code>#合伙人登录</code></li><li><code>#合伙人测试</code>：实际执行任务，提交主分、子项评分和乐评。</li><li><code>#合伙人日志</code></li></ul><p>主人管理面板的“网易云任务”可选择固定评论库、Responses API 或本机 Codex CLI 生成乐评。AI 模式结合歌曲资料联网核实，失败时跳过评论；本机 Codex 使用已有登录，无需 API 密钥。默认保留固定模式，详见 <a href="./features/netease-partner.html">合伙人配置</a>。</p><h2 id="群管理" tabindex="-1">群管理 <a class="header-anchor" href="#群管理" aria-label="Permalink to &quot;群管理&quot;">​</a></h2><ul><li><code>#荷花群成员</code></li><li><code>#荷花群成员 123456</code></li><li><code>#群清理退群 10001</code></li><li><code>#群清理退群 10001 123456</code></li></ul><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><ul><li><code>#权限列表</code></li><li><code>#权限配置</code></li><li><code>#权限允许用户 10001</code></li><li><code>#权限拒绝用户 10001</code></li><li><code>#权限移除用户 10001</code></li><li><code>#权限允许群 123456</code></li><li><code>#权限拒绝群 123456</code></li><li><code>#权限设置 checkin.register allow</code></li><li><code>#自动签到黑名单</code></li><li><code>#自动签到白名单</code></li><li><code>#添加黑名单 10001</code></li><li><code>#删除白名单 10001</code></li><li><code>#签到黑名单列表</code></li></ul><h2 id="远程-spawn" tabindex="-1">远程 spawn <a class="header-anchor" href="#远程-spawn" aria-label="Permalink to &quot;远程 spawn&quot;">​</a></h2><ul><li><code>#远程2FA初始化</code></li><li><code>#远程2FA状态</code></li><li><code>#远程spawn &lt;otp&gt; &lt;shell&gt; &lt;command&gt;</code></li><li><code>#远程管理员spawn &lt;otp&gt; &lt;shell&gt; &lt;command&gt;</code></li><li><code>#远程下载 &lt;otp&gt; &lt;path&gt;</code></li><li><code>#远程上传 &lt;otp&gt; &lt;path&gt;</code></li><li><code>#远程上传覆盖 &lt;otp&gt; &lt;path&gt;</code></li></ul><p>远程指令只允许 bot 主人使用，并且必须带 6 位 TOTP。</p><h2 id="代操作与批量执行" tabindex="-1">代操作与批量执行 <a class="header-anchor" href="#代操作与批量执行" aria-label="Permalink to &quot;代操作与批量执行&quot;">​</a></h2><ul><li><code>#代 @用户 #体力2</code></li><li><code>#执行 全员 间隔=5 -- #体力</code></li><li><code>#执行 123456789 群=私聊 -- #面板2</code></li><li>兼容旧 <code>#execute in:here as:123456789 gap:5 hold:false run:#体力2</code>。</li></ul><p>仅机器人主人可发起，目标权限和 profile 由目标用户决定。完整选项见 <a href="./execute.html">代操作说明</a>。</p>',65)])])}const f=o(c,[["render",a]]);export{s as __pageData,f as default};
